CREATE TABLE external_identities(provider TEXT NOT NULL,issuer TEXT NOT NULL,subject TEXT NOT NULL,user_id TEXT NOT NULL REFERENCES users(id),organization_id TEXT NOT NULL REFERENCES organizations(id),external_organization_id TEXT NOT NULL DEFAULT '',state TEXT NOT NULL CHECK(state IN ('ACTIVE','REVOKED')),created_by TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,PRIMARY KEY(provider,issuer,subject));
CREATE TABLE provider_events(id TEXT PRIMARY KEY,provider TEXT NOT NULL,event_id TEXT NOT NULL,subject_reference TEXT NOT NULL,event_type TEXT NOT NULL,provider_status TEXT NOT NULL,normalized_status TEXT NOT NULL,occurred_at TEXT NOT NULL,received_at TEXT NOT NULL,payload_sha256 TEXT NOT NULL,provider_timestamp INTEGER NOT NULL,normalized_json TEXT NOT NULL,UNIQUE(provider,event_id));
CREATE TRIGGER provider_events_no_update BEFORE UPDATE ON provider_events BEGIN SELECT RAISE(ABORT,'Immutable provider receipt'); END;
CREATE TRIGGER provider_events_no_delete BEFORE DELETE ON provider_events BEGIN SELECT RAISE(ABORT,'Immutable provider receipt'); END;
CREATE TABLE artifact_processing_results(id TEXT PRIMARY KEY,artifact_id TEXT NOT NULL REFERENCES artifacts(id),source_sha256 TEXT NOT NULL,scan_status TEXT NOT NULL,extraction_status TEXT,report_json TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TRIGGER processing_results_no_update BEFORE UPDATE ON artifact_processing_results BEGIN SELECT RAISE(ABORT,'Immutable processing receipt'); END;
CREATE TRIGGER processing_results_no_delete BEFORE DELETE ON artifact_processing_results BEGIN SELECT RAISE(ABORT,'Immutable processing receipt'); END;
